/* From Uiverse.io by ahmed150up - Tags: card */
.__UIV_SCOPE__ .card-container {
  width: 330px;
  background-color: #fff;
  border: 1px solid #ccc;
  border-radius: 5px;
  box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.1);
}

.__UIV_SCOPE__ .card-header {
  background-color: #333;
  color: #fff;
  padding: 10px;
  font-size: 20px;
  border-top-left-radius: 5px;
  border-top-right-radius: 5px;
}

.__UIV_SCOPE__ .card-body {
  padding: 10px;
}

.__UIV_SCOPE__ .card-footer {
  display: flex;
  justify-content: space-between;
  padding: 10px;
}

.__UIV_SCOPE__ .mute-button, .__UIV_SCOPE__ .unmute-button {
  background-color: #333;
  color: white;
  padding: 12px 20px;
  border: none;
  cursor: pointer;
  width: 100%;
}

.__UIV_SCOPE__ .mute-button:hover, .__UIV_SCOPE__ .unmute-button:hover {
  background-color: rgb(247, 247, 247);
  color: rgb(0, 0, 0);
}
